	//                 "currency":"USDT",
	//                 "withdraw_fee_currency":"USDT",
	//                 "withdraw_status":0,
	//                 "chain":"OMNI"
	//             },
	//             {
	//                 "deposit_status":1,
	//                 "min_deposit_amount":10,
	//                 "withdraw_fee_rate":0,
	//                 "min_withdraw_amount":10,
	//                 "min_withdraw_fee":3,
	//                 "currency":"USDT",
	//                 "withdraw_fee_currency":"USDT",
	//                 "withdraw_status":1,
	//                 "chain":"ERC20"
	//             },
	//             {
	//                 "deposit_status":0,
	//                 "min_deposit_amount":0,
	//                 "withdraw_fee_rate":0,
	//                 "min_withdraw_amount":0,
	//                 "min_withdraw_fee":0,
