func (this *Digifinex) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// spot: fetchTicker, fetchTickers
	//
	//     {
	//         "last":0.021957,
	//         "symbol": "btc_usdt",
	//         "base_vol":2249.3521732227,
	//         "change":-0.6,
	//         "vol":102443.5111,
	//         "sell":0.021978,
	//         "low":0.021791,
	//         "buy":0.021946,
	//         "high":0.022266,
	//         "date"1564518452, // injected from fetchTicker/fetchTickers
	//     }
	//
	// swap: fetchTicker, fetchTickers
	//
	//     {
	//         "instrument_id": "BTCUSDTPERP",
	//         "index_price": "20141.9967",
	//         "mark_price": "20139.3404",
	//         "max_buy_price": "21146.4838",
	//         "min_sell_price": "19132.2725",
	//         "best_bid": "20140.0998",
	//         "best_bid_size": "3116",
	//         "best_ask": "20140.0999",
	//         "best_ask_size": "9004",
	//         "high_24h": "20410.6496",
	//         "open_24h": "20308.6998",
	//         "low_24h": "19600",
	//         "last": "20140.0999",
	//         "last_qty": "2",
	//         "volume_24h": "49382816",
	//         "price_change_percent": "-0.008301855936636448",
	//         "open_interest": "-",
	//         "timestamp": 1663221614998
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var indexPrice any = this.SafeNumber(ticker, "index_price")
	var marketType any = Ternary(IsTrue((!IsEqual(indexPrice, nil))), "contract", "spot")
	var marketId any = this.SafeStringUpper2(ticker, "symbol", "instrument_id")
	var symbol any = this.SafeSymbol(marketId, market, nil, marketType)
	market = this.SafeMarket(marketId, market, nil, marketType)
	var timestamp any = this.SafeTimestamp(ticker, "date")
	if IsTrue(IsEqual(GetValue(market, "swap"), true)) {
		timestamp = this.SafeInteger(ticker, "timestamp")
	}
	var last any = this.SafeString(ticker, "last")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString2(ticker, "high", "high_24h"),
		"low":           this.SafeString2(ticker, "low", "low_24h"),
		"bid":           this.SafeString2(ticker, "buy", "best_bid"),
		"bidVolume":     this.SafeString(ticker, "best_bid_size"),
		"ask":           this.SafeString2(ticker, "sell", "best_ask"),
		"askVolume":     this.SafeString(ticker, "best_ask_size"),
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open_24h"),
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString2(ticker, "change", "price_change_percent"),
		"average":       nil,
		"baseVolume":    this.SafeString2(ticker, "vol", "volume_24h"),
		"quoteVolume":   this.SafeString(ticker, "base_vol"),
		"markPrice":     this.SafeString(ticker, "mark_price"),
		"indexPrice":    indexPrice,
		"info":          ticker,
	}, market)
}
func (this *Digifinex) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// spot: fetchTrades
	//
	//     {
	//         "date":1564520003,
	//         "id":1596149203,
	//         "amount":0.7073,
	//         "type":"buy",
	//         "price":0.02193,
	//     }
	//
	// swap: fetchTrades
	//
	//     {
	//         "instrument_id": "BTCUSDTPERP",
	//         "trade_id": "1595190773677035521",
	//         "direction": "4",
	//         "volume": "4",
	//         "price": "16188.3",
	//         "trade_time": 1669158092314
	//     }
	//
	// spot: fetchMyTrades
	//
	//     {
	//         "symbol": "BTC_USDT",
	//         "order_id": "6707cbdcda0edfaa7f4ab509e4cbf966",
	//         "id": 28457,
	//         "price": 0.1,
	//         "amount": 0,
	//         "fee": 0.096,
	//         "fee_currency": "USDT",
	//         "timestamp": 1499865549,
	//         "side": "buy", // or "side": "sell_market"
	//         "is_maker": true
	//     }
	//
	// swap: fetchMyTrades
	//
	//     {
	//         "trade_id": "1590136768424841218",
	//         "instrument_id": "BTCUSDTPERP",
	//         "order_id": "1590136768156405760",
	//         "type": 1,
	//         "order_type": 8,
	//         "price": "18514.5",
	//         "size": "1",
	//         "fee": "0.00925725",
	//         "close_profit": "0",
	//         "leverage": "20",
	//         "trade_type": 0,
	//         "match_role": 1,
	//         "trade_time": 1667953123562
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id any = this.SafeString2(trade, "id", "trade_id")
	var orderId any = this.SafeString(trade, "order_id")
	var priceString any = this.SafeString(trade, "price")
	var amountString any = this.SafeStringN(trade, []any{"amount", "volume", "size"})
	var marketId any = this.SafeStringUpper2(trade, "symbol", "instrument_id")
	var symbol any = this.SafeSymbol(marketId, market)
	if IsTrue(IsEqual(market, nil)) {
		market = this.SafeMarket(marketId)
	}
	var timestamp any = this.SafeTimestamp2(trade, "date", "timestamp")
	var side any = this.SafeString2(trade, "type", "side")
	var typeVar any = nil
	var takerOrMaker any = nil
	if IsTrue(IsEqual(GetValue(market, "type"), "swap")) {
		timestamp = this.SafeInteger(trade, "trade_time")
		var orderType any = this.SafeString(trade, "order_type")
		var tradeRole any = this.SafeString(trade, "match_role")
		var direction any = this.SafeString(trade, "direction")
		if IsTrue(!IsEqual(orderType, nil)) {
			typeVar = Ternary(IsTrue((IsEqual(orderType, "0"))), "limit", nil)
		}
		if IsTrue(IsEqual(tradeRole, "1")) {
			takerOrMaker = "taker"
		} else if IsTrue(IsEqual(tradeRole, "2")) {
			takerOrMaker = "maker"
		} else {
			takerOrMaker = nil
		}
		if IsTrue(IsTrue((IsEqual(side, "1"))) || IsTrue((IsEqual(direction, "1")))) {
			// side = 'open long';
			side = "buy"
		} else if IsTrue(IsTrue((IsEqual(side, "2"))) || IsTrue((IsEqual(direction, "2")))) {
			// side = 'open short';
			side = "sell"
		} else if IsTrue(IsTrue((IsEqual(side, "3"))) || IsTrue((IsEqual(direction, "3")))) {
			// side = 'close long';
			side = "sell"
		} else if IsTrue(IsTrue((IsEqual(side, "4"))) || IsTrue((IsEqual(direction, "4")))) {
			// side = 'close short';
			side = "buy"
		}
	} else {
		if IsTrue(IsEqual(side, nil)) {
			panic(ExchangeError(Add(this.Id, " parseTrade() returned no side")))
		}
		var parts []string = Split(side, "_")
		side = this.SafeString(parts, 0)
		typeVar = this.SafeString(parts, 1)
		if IsTrue(IsEqual(typeVar, nil)) {
			typeVar = "limit"
		}
		var isMaker any = this.SafeValue(trade, "is_maker")
		takerOrMaker = Ternary(IsTrue((IsEqual(isMaker, true))), "maker", "taker")
	}
	var fee any = nil
	var feeCostString any = this.SafeString(trade, "fee")
	if IsTrue(!IsEqual(feeCostString, nil)) {
		var feeCurrencyId any = this.SafeString(trade, "fee_currency")
		var feeCurrencyCode any = nil
		if IsTrue(!IsEqual(feeCurrencyId, nil)) {
			feeCurrencyCode = this.SafeCurrencyCode(feeCurrencyId)
		}
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"type":         typeVar,
		"order":        orderId,
		"side":         side,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"takerOrMaker": takerOrMaker,
		"fee":          fee,
	}, market)
}

